{% extends "templates/print/ph_basis.html" %}
{% set phasen = ["Anfrage","Planung","Angebot","Auftrag","Bestellung","Lieferung","Montage","Uebergabe"] %}
{% set labels = {"Anfrage":"Anfrage","Planung":"Planung","Angebot":"Angebot","Auftrag":"Auftrag","Bestellung":"Bestellung","Lieferung":"Lieferung","Montage":"Montage","Uebergabe":"Übergabe"} %}
{% set aktiv = phasen.index(doc.status) if doc.status in phasen else (8 if doc.status == "Abgeschlossen" else 0) %}
{% block titel %}Projektstatus {{ doc.name }}{% endblock %}
{% block kopfrechts %}Projekt {{ doc.name }}<br>Stand {{ ph_datum(frappe.utils.nowdate()) }}{% endblock %}
{% block css %}.ph-ph{display:flex;gap:2mm;margin:4mm 0 6mm}.ph-ph div{flex:1;text-align:center;font-size:7pt;letter-spacing:.06em;text-transform:uppercase;padding:2mm 1mm;background:#f3f1ec;color:#8a7a66;border-radius:1mm}.ph-ph .e{background:#30373e;color:#fff}.ph-ph .a{background:#8a7a66;color:#fff;font-weight:600}{% endblock %}
{% block inhalt %}
<h1>{{ doc.titel }}</h1>
<p style="color:#6b7280">{{ doc.kunde_name }}{% if doc.objekt_ort %} · {{ doc.objekt_ort }}{% endif %} · {{ _(doc.projektart) }}</p>
<div class="ph-ph">{% for p in phasen %}<div class="{% if loop.index0 < aktiv %}e{% elif loop.index0 == aktiv %}a{% endif %}">{{ labels[p] }}</div>{% endfor %}</div>
{% if doc.kurzbeschreibung %}<p>{{ doc.kurzbeschreibung }}</p>{% endif %}
<h2>Nächste Termine</h2>
<div class="ph-feld"><b>Liefertermin (geplant)</b> {{ ph_datum(doc.liefertermin_geplant) or "wird mit der Liefermeldung des Herstellers fixiert" }}</div>
<div class="ph-feld"><b>Montage</b> {% if doc.montage_von %}{{ ph_datum(doc.montage_von) }}{% if doc.montage_bis and doc.montage_bis != doc.montage_von %} – {{ ph_datum(doc.montage_bis) }}{% endif %}{% else %}offen{% endif %}</div>
<div class="ph-feld"><b>Übergabe</b> {{ ph_datum(doc.uebergabe_am) or "offen" }}</div>
{% set montagen = frappe.get_all("PH Montageauftrag", filters={"projekt": doc.name, "status": ["not in", ["Abgebrochen"]]}, fields=["start","status","ort"], order_by="start asc") %}
{% if montagen %}<table class="ph-tabelle"><thead><tr><th>Montagetermin</th><th>Ort</th><th>Status</th></tr></thead><tbody>{% for m in montagen %}<tr><td>{{ frappe.utils.format_datetime(m.start, "dd.MM.yyyy HH:mm") }}</td><td>{{ m.ort or "" }}</td><td>{{ _(m.status) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if doc.positionen %}<h2>Positionen</h2>
<table class="ph-tabelle"><thead><tr><th>Produkt</th><th>Marke</th><th>Raum</th><th class="zahl">Menge</th><th>Status</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.bezeichnung }}{% if p.ausfuehrung_text %}<br><span style="color:#6b7280;font-size:8.5pt">{{ p.ausfuehrung_text }}</span>{% endif %}</td><td>{{ p.marke or "" }}</td><td>{{ p.raum or "" }}</td><td class="zahl">{{ p.menge }}</td><td>{{ p.status }}</td></tr>{% endfor %}
</tbody></table>{% endif %}
{% set gewerke = frappe.get_all("PH Fremdgewerk", filters={"projekt": doc.name, "kunde_sichtbar": 1, "status": ["!=", "Abgesagt"]}, fields=["gewerk","partner_text","leistung","termin_von","status"], order_by="termin_von asc") %}
{% if gewerke %}<h2>Koordinierte Gewerke</h2>
<table class="ph-tabelle"><thead><tr><th>Gewerk</th><th>Partnerbetrieb</th><th>Leistung</th><th>Termin</th><th>Status</th></tr></thead><tbody>
{% for g in gewerke %}<tr><td>{{ g.gewerk }}</td><td>{{ g.partner_text or "Partnerbetrieb (Name folgt)" }}</td><td>{{ g.leistung or "" }}</td><td>{{ frappe.utils.format_datetime(g.termin_von, "dd.MM.yyyy HH:mm") if g.termin_von else "offen" }}</td><td>{{ _(g.status) }}</td></tr>{% endfor %}
</tbody></table>
<p class="ph-hinweis">{{ ph_einstellungen_projekte().haftungshinweis_fremdgewerke }}</p>{% endif %}
{% if doc.portal_hinweis %}<p class="ph-hinweis">{{ doc.portal_hinweis }}</p>{% endif %}
<p style="color:#6b7280;font-size:8.5pt">Dieser Statusbericht enthält keine Preise. Angebote und Rechnungen erhalten Sie gesondert bzw. im Kundenportal.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set s = doc.sprache_bericht or "de" %}
{% set t = montage_text %}
{% set projekt = frappe.get_doc("PH Projekt", doc.projekt) %}
{% block titel %}{{ t(s, "montagebericht") }} {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ t(s, "montagebericht") }} {{ doc.name }}<br>{{ t(s, "datum") }} {{ ph_datum(doc.start) }}{% endblock %}
{% block css %}.ph-fotos{display:flex;flex-wrap:wrap;gap:3mm}.ph-fotos figure{margin:0;width:44mm}.ph-fotos img{width:44mm;height:33mm;object-fit:cover;border-radius:1mm}.ph-fotos figcaption{font-size:7pt;color:#6b7280}.ph-sig{display:flex;gap:10mm;margin-top:8mm}.ph-sig div{flex:1;border-top:1px solid #30373e;padding-top:2mm;font-size:8pt;color:#6b7280}.ph-sig img{max-height:22mm;display:block;margin-bottom:1mm}{% endblock %}
{% block inhalt %}
<h1>{{ t(s, "montagebericht") }}</h1>
<div class="ph-feld"><b>{{ t(s, "projekt") }}</b> {{ projekt.titel }} ({{ projekt.name }})</div>
<div class="ph-feld"><b>{{ t(s, "kunde") }}</b> {{ projekt.kunde_name }}</div>
<div class="ph-feld"><b>{{ t(s, "einsatzort") }}</b> {{ doc.strasse or "" }}, {{ doc.plz or "" }} {{ doc.ort or "" }}</div>
<div class="ph-feld"><b>{{ t(s, "datum") }}</b> {{ frappe.utils.format_datetime(doc.tatsaechlich_start or doc.start, "dd.MM.yyyy HH:mm") }}{% if doc.tatsaechlich_ende %} – {{ frappe.utils.format_datetime(doc.tatsaechlich_ende, "HH:mm") }}{% endif %}</div>
<div class="ph-feld"><b>{{ t(s, "team") }}</b> {% for m in doc.team %}{{ frappe.db.get_value("User", m.user, "full_name") or m.user }}{% if not loop.last %}, {% endif %}{% endfor %}</div>
<h2>{{ t(s, "leistungen") }}</h2>
<table class="ph-tabelle"><thead><tr><th>{{ t(s, "leistung") }}</th><th class="zahl">{{ t(s, "stunden") }}</th><th>{{ t(s, "erledigt") }}</th></tr></thead><tbody>
{% for l in doc.leistungen %}<tr><td>{{ l.beschreibung }}</td><td class="zahl">{{ l.dauer_h_ist or l.dauer_h_geplant or "" }}</td><td>{{ "✓" if l.erledigt else t(s, "offen") }}</td></tr>{% endfor %}
</tbody></table>
{% if doc.bericht %}<h2>{{ t(s, "bericht") }}</h2><div>{{ doc.bericht }}</div>{% endif %}
{% set vorher = doc.fotos | selectattr("art", "equalto", "vorher") | list %}{% set nachher = doc.fotos | selectattr("art", "equalto", "nachher") | list %}
{% if vorher %}<h2>{{ t(s, "fotos_vorher") }}</h2><div class="ph-fotos">{% for f in vorher %}<figure><img src="{{ frappe.utils.get_url(f.bild) }}"><figcaption>{{ f.hinweis or "" }}</figcaption></figure>{% endfor %}</div>{% endif %}
{% if nachher %}<h2>{{ t(s, "fotos_nachher") }}</h2><div class="ph-fotos">{% for f in nachher %}<figure><img src="{{ frappe.utils.get_url(f.bild) }}"><figcaption>{{ f.hinweis or "" }}</figcaption></figure>{% endfor %}</div>{% endif %}
<h2>{{ t(s, "vorschaeden") }}</h2>
{% set vs = doc.fotos | selectattr("art", "equalto", "vorschaden") | list %}
{% if doc.vorschaeden_keine and not vs and not doc.vorschaeden_text %}<p>{{ t(s, "keine_vorschaeden") }}</p>{% else %}<p>{{ doc.vorschaeden_text or "" }}{% if doc.vorschaeden_bestaetigt %} · {{ t(s, "vom_kunden_bestaetigt") }}{% endif %}</p>{% if vs %}<div class="ph-fotos">{% for f in vs %}<figure><img src="{{ frappe.utils.get_url(f.bild) }}"><figcaption>{{ f.hinweis or "" }}</figcaption></figure>{% endfor %}</div>{% endif %}{% endif %}
{% if doc.geraete %}<h2>{{ t(s, "geraete") }}</h2>
<table class="ph-tabelle"><thead><tr><th>{{ t(s, "geraet") }}</th><th>E-Nr.</th><th>S/N</th><th>{{ t(s, "eingebaut") }}</th><th>{{ t(s, "funktion") }}</th></tr></thead><tbody>
{% for g in doc.geraete %}<tr><td>{{ g.marke or "" }} {{ g.bezeichnung }}</td><td>{{ g.e_nummer or "" }}{% if g.fd_nummer %} / FD {{ g.fd_nummer }}{% endif %}</td><td>{{ g.seriennummer or "" }}</td><td>{{ "✓" if g.eingebaut else "–" }}</td><td>{{ "✓" if g.funktion_geprueft else "–" }}</td></tr>{% endfor %}
</tbody></table>{% endif %}
<h2>{{ t(s, "maengel") }}</h2>
{% if doc.maengel %}<table class="ph-tabelle"><thead><tr><th>{{ t(s, "beschreibung") }}</th><th>{{ t(s, "frist") }}</th><th>Status</th></tr></thead><tbody>{% for m in doc.maengel %}<tr><td>{{ m.beschreibung }}</td><td>{{ ph_datum(m.frist) }}</td><td>{{ m.status }}</td></tr>{% endfor %}</tbody></table>{% else %}<p>{{ t(s, "keine_maengel") }}</p>{% endif %}
<p class="ph-hinweis">{{ t(s, "bestaetigung") }}</p>
<div class="ph-sig"><div>{% if doc.unterschrift_kunde %}<img src="{{ doc.unterschrift_kunde }}">{% endif %}{{ t(s, "unterschrift_kunde") }}{% if doc.unterschrift_name %} · {{ doc.unterschrift_name }}{% endif %}{% if doc.unterschrift_am %} · {{ frappe.utils.format_datetime(doc.unterschrift_am, "dd.MM.yyyy HH:mm") }}{% endif %}</div><div>{% if doc.unterschrift_monteur %}<img src="{{ doc.unterschrift_monteur }}">{% endif %}{{ t(s, "unterschrift_monteur") }}</div></div>
<p style="color:#6b7280;font-size:8.5pt;margin-top:6mm">{{ t(s, "danke") }} {% if s == "de" %}{{ ph_einstellungen_projekte().montagebericht_fusstext }}{% endif %}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set s = doc.sprache or "de" %}{% set t = montage_text %}
{% set projekt = frappe.get_doc("PH Projekt", doc.projekt) %}
{% block titel %}{{ t(s, "abnahmeprotokoll") }} {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ t(s, "abnahmeprotokoll") }} {{ doc.name }}<br>{{ t(s, "datum") }} {{ ph_datum(doc.datum) }}{% endblock %}
{% block css %}.ph-sig{display:flex;gap:10mm;margin-top:8mm}.ph-sig div{flex:1;border-top:1px solid #30373e;padding-top:2mm;font-size:8pt;color:#6b7280}.ph-sig img{max-height:22mm;display:block;margin-bottom:1mm}.m{color:#b45309;font-weight:600}.ok{color:#15803d}{% endblock %}
{% block inhalt %}
<h1>{{ t(s, "abnahmeprotokoll") }}</h1>
<div class="ph-feld"><b>{{ t(s, "projekt") }}</b> {{ projekt.titel }} ({{ projekt.name }})</div>
<div class="ph-feld"><b>{{ t(s, "kunde") }}</b> {{ projekt.kunde_name }}</div>
<div class="ph-feld"><b>{{ t(s, "einsatzort") }}</b> {{ doc.ort or (projekt.objekt_strasse ~ ", " ~ projekt.objekt_ort) }}</div>
<div class="ph-feld"><b>{{ t(s, "anwesend") }}</b> {{ doc.anwesend_kunde or "" }}{% if doc.anwesend_studio %} · {{ frappe.db.get_value("User", doc.anwesend_studio, "full_name") }} (Platzhirsch){% endif %}</div>
<h2>{{ t(s, "position") }}en</h2>
<table class="ph-tabelle"><thead><tr><th>#</th><th>{{ t(s, "position") }}</th><th>{{ t(s, "zustand") }}</th><th>{{ t(s, "beschreibung") }}</th><th>{{ t(s, "frist") }}</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ loop.index }}</td><td>{{ p.bezeichnung }}</td><td class="{{ 'ok' if p.zustand == 'ok' else 'm' }}">{{ t(s, p.zustand) }}{% if p.erledigt %} ✓{% endif %}</td><td>{{ p.beschreibung or "" }}</td><td>{{ ph_datum(p.frist) }}</td></tr>{% endfor %}
</tbody></table>
<p class="ph-hinweis">{% if doc.abnahme_erklaert and not doc.maengel_offen %}{{ t(s, "abnahme_erklaert") }}{% else %}{{ t(s, "abnahme_vorbehalt") }}{% endif %}{% if doc.vorbehalte %}<br><b>{{ t(s, "vorbehalte") }}:</b> {{ doc.vorbehalte }}{% endif %}</p>
{% if doc.naechste_schritte %}<h2>{{ t(s, "naechste_schritte") }}</h2><p>{{ doc.naechste_schritte }}</p>{% endif %}
<div class="ph-sig"><div>{% if doc.unterschrift_kunde %}<img src="{{ doc.unterschrift_kunde }}">{% endif %}{{ t(s, "unterschrift_kunde") }}{% if doc.unterschrift_kunde_name %} · {{ doc.unterschrift_kunde_name }}{% endif %}{% if doc.unterzeichnet_am %} · {{ frappe.utils.format_datetime(doc.unterzeichnet_am, "dd.MM.yyyy HH:mm") }}{% endif %}</div><div>{% if doc.unterschrift_studio %}<img src="{{ doc.unterschrift_studio }}">{% endif %}{{ t(s, "unterschrift_studio") }}</div></div>
<p style="color:#6b7280;font-size:8.5pt;margin-top:6mm">{% if s == "de" %}{{ ph_einstellungen_projekte().abnahme_fusstext }}{% endif %} {{ t(s, "koordination") }}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set url = ph_einstellungen_projekte().portal_basis_url ~ "/pass/" ~ doc.name %}
{% block titel %}Produktpass {{ doc.name }}{% endblock %}
{% block kopfrechts %}Produktpass {{ doc.name }}<br>{{ ph_datum(doc.lieferdatum) }}{% endblock %}
{% block css %}@page{size:A5}.ph-pp{display:flex;gap:6mm;align-items:flex-start}.ph-pp .l{flex:1}.ph-qr{border:1px solid #d9d4cc;padding:1mm;border-radius:1mm}{% endblock %}
{% block inhalt %}
<div class="ph-pp"><div class="l">
<h1>{{ doc.produkt_name }}</h1>
<p style="color:#6b7280;margin-top:-2mm">{{ doc.marke or "" }}{% if doc.kategorie %} · {{ doc.kategorie }}{% endif %}</p>
{% if doc.ausfuehrung_text %}<div class="ph-feld"><b>Ausführung</b> {{ doc.ausfuehrung_text }}</div>{% endif %}
{% if doc.seriennummer %}<div class="ph-feld"><b>Seriennummer</b> {{ doc.seriennummer }}</div>{% endif %}
<div class="ph-feld"><b>Geliefert am</b> {{ ph_datum(doc.lieferdatum) or "–" }}</div>
<div class="ph-feld"><b>Garantie</b> {% if doc.garantie_monate %}{{ doc.garantie_monate }} Monate{% if doc.garantie_bis %} (bis {{ ph_datum(doc.garantie_bis) }}){% endif %}{% else %}lt. Hersteller{% endif %}</div>
</div><div class="ph-qr">{{ ph_qr_svg(url) }}<div style="font-size:6.5pt;color:#6b7280;text-align:center;margin-top:1mm">Digitaler Produktpass</div></div></div>
{% if doc.materialien %}<h2>Materialien</h2><table class="ph-tabelle"><tbody>{% for m in doc.materialien %}<tr><td>{{ m.material }}</td><td>{{ m.anteil or "" }}</td><td>{{ m.herkunft or "" }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if doc.pflege %}<h2>Pflege{% if doc.pflegekategorie %} ({{ doc.pflegekategorie }}){% endif %}</h2><ul style="padding-left:5mm">{% for p in doc.pflege %}<li>{{ p.hinweis }}{% if p.intervall %} <span style="color:#6b7280">({{ p.intervall }})</span>{% endif %}</li>{% endfor %}</ul>{% endif %}
{% if doc.garantie_hinweis %}<p class="ph-hinweis">{{ doc.garantie_hinweis }}</p>{% endif %}
{% set dok = doc.dokumente | selectattr("kunde_sichtbar") | list %}{% if dok %}<h2>Dokumente</h2><ul style="padding-left:5mm">{% for d in dok %}<li>{{ d.titel }} <span style="color:#6b7280">({{ d.art }})</span></li>{% endfor %}</ul>{% endif %}
<p style="color:#6b7280;font-size:7.5pt">Aktuelle Pflegehinweise, Garantiebelege und Serviceanfragen: {{ url }}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Einwilligungsnachweis {{ doc.name }}{% endblock %}
{% block kopfrechts %}Referenz-Freigabe {{ doc.name }}<br>Status {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Nachweis der Einwilligung (Art. 7 Abs. 1 DSGVO)</h1>
<div class="ph-feld"><b>Projekt</b> {{ doc.projekt }}</div>
<div class="ph-feld"><b>Kunde</b> {{ doc.kontakt }}</div>
<div class="ph-feld"><b>Nennung</b> {% if doc.anzeige_art == "vorname_ort" %}Vorname und Ort: {{ doc.anzeige_vorname }}, {{ doc.anzeige_ort }}{% else %}anonym („am Bodensee“){% endif %}</div>
<div class="ph-feld"><b>Erteilt am</b> {{ frappe.utils.format_datetime(doc.einwilligung_zeitpunkt, "dd.MM.yyyy HH:mm") }} über {{ doc.einwilligung_kanal }}</div>
<div class="ph-feld"><b>Textversion</b> {{ doc.einwilligung_version }} ({{ doc.einwilligung_textstatus }})</div>
{% if doc.widerruf_zeitpunkt %}<div class="ph-feld"><b>Widerrufen am</b> {{ frappe.utils.format_datetime(doc.widerruf_zeitpunkt, "dd.MM.yyyy HH:mm") }} über {{ doc.widerruf_kanal }}</div>{% endif %}
<h2>Wortlaut, den der Kunde gesehen hat</h2>
<div class="ph-hinweis" style="white-space:pre-wrap">{{ doc.einwilligung_text }}</div>
<h2>Freigegebene Fotos</h2>
<table class="ph-tabelle"><thead><tr><th>Foto</th><th>Phase</th><th>Titel</th><th>Von</th></tr></thead><tbody>{% for b in doc.bilder %}<tr><td>{{ b.foto }}</td><td>{{ b.phase }}</td><td>{{ b.titel or b.alt or "" }}</td><td>{{ b.von }}</td></tr>{% endfor %}</tbody></table>
<h2>Verlauf</h2>
<table class="ph-tabelle"><tbody>{% for v in (doc.verlauf if doc.verlauf is not string else frappe.parse_json(doc.verlauf)) or [] %}<tr><td>{{ v.am }}</td><td>{{ v.was }}</td><td>{{ v.von }}</td></tr>{% endfor %}</tbody></table>
<p class="ph-hinweis">Interner Nachweis. Nach Widerruf bleibt dieser Datensatz als Nachweis erhalten; die Bildkopien der Referenz sind gelöscht.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Aufmaßprotokoll {{ doc.name }}{% endblock %}
{% block kopfrechts %}Aufmaß {{ doc.name }}<br>{{ ph_datum(doc.datum) }}<br>Status {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Aufmaßprotokoll</h1>
<div class="ph-feld"><b>Projekt</b> {{ doc.projekt }} · {{ frappe.db.get_value("PH Projekt", doc.projekt, "titel") or "" }}</div>
<div class="ph-feld"><b>Objekt</b> {{ doc.objekt_text or "" }}{% if doc.etage %} · Etage {{ doc.etage }}{% endif %}{% if doc.aufzug %} · Aufzug vorhanden{% endif %}</div>
<div class="ph-feld"><b>Aufgenommen von</b> {{ frappe.db.get_value("User", doc.aufgenommen_von, "full_name") or doc.aufgenommen_von or "" }}{% if doc.geprueft_von %} · geprüft von {{ frappe.db.get_value("User", doc.geprueft_von, "full_name") or doc.geprueft_von }} am {{ ph_datum(doc.geprueft_am) }}{% endif %}</div>
{% if doc.zugang_hinweis %}<div class="ph-feld"><b>Zugang/Transportweg</b> {{ doc.zugang_hinweis }}</div>{% endif %}
<h2>Räume</h2>
<table class="ph-tabelle"><tr><th>Raum</th><th>Länge</th><th>Breite</th><th>Höhe</th><th>Fläche</th><th>Notiz</th></tr>
{% for r in doc.raeume %}<tr><td>{{ r.raum }}</td><td>{{ r.laenge_mm or "" }} mm</td><td>{{ r.breite_mm or "" }} mm</td><td>{{ r.hoehe_mm or "" }} mm</td><td>{{ "%.2f"|format(r.flaeche_m2 or 0) }} m²</td><td>{{ r.notiz or "" }}</td></tr>{% endfor %}
</table>
{% if doc.masse %}<h2>Maße</h2>
<table class="ph-tabelle"><tr><th>Raum</th><th>Bezug</th><th>Bezeichnung</th><th>Art</th><th>Wert</th></tr>
{% for m in doc.masse %}<tr><td>{{ m.raum or "" }}</td><td>{{ m.bezug or "" }}</td><td>{{ m.bezeichnung }}</td><td>{{ _(m.art) }}</td><td>{{ m.wert_mm }} mm{% if m.toleranz_mm %} ± {{ m.toleranz_mm }}{% endif %}</td></tr>{% endfor %}
</table>{% endif %}
{% if doc.anschluesse %}<h2>Anschlüsse</h2>
<table class="ph-tabelle"><tr><th>Raum</th><th>Anschluss</th><th>Zustand</th><th>Bezug</th><th>X</th><th>Y</th><th>Höhe</th><th>Notiz</th></tr>
{% for a in doc.anschluesse %}<tr><td>{{ a.raum or "" }}</td><td>{{ a.art }}{% if a.durchmesser_mm %} Ø {{ a.durchmesser_mm }}{% endif %}</td><td>{{ a.zustand }}</td><td>{{ a.bezug or "" }}</td><td>{{ a.x_mm or "" }}</td><td>{{ a.y_mm or "" }}</td><td>{{ a.hoehe_mm or "" }}</td><td>{{ a.notiz or "" }}</td></tr>{% endfor %}
</table>{% endif %}
{% if doc.plausibilitaet %}<h2>Hinweise</h2><p>{{ doc.plausibilitaet | replace("\n", "<br>") }}</p>{% endif %}
{% if doc.skizze and doc.skizze.lower().endswith((".png", ".jpg", ".jpeg", ".webp")) %}<h2>Skizze</h2><img src="{{ doc.skizze }}" style="max-width:100%;max-height:120mm">{% endif %}
{% if doc.notiz %}<h2>Notiz</h2><div>{{ doc.notiz }}</div>{% endif %}
<p class="ph-klein">Maße in Millimeter. Das Aufmaß ist Grundlage der Planung; vor Bestellung werden kritische Maße erneut geprüft.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Nachtrag {{ doc.nummer_im_projekt }} · {{ doc.name }}{% endblock %}
{% block kopfrechts %}Nachtrag {{ doc.name }}<br>Projekt {{ doc.projekt }}<br>{{ ph_datum(doc.datum) }}{% endblock %}
{% block inhalt %}
<h1>Nachtrag Nr. {{ doc.nummer_im_projekt }}: {{ doc.bezeichnung }}</h1>
<div class="ph-feld"><b>Projekt</b> {{ frappe.db.get_value("PH Projekt", doc.projekt, "titel") or doc.projekt }}</div>
<div class="ph-feld"><b>Grund</b> {{ _(doc.grund) }}</div>
{% if doc.beschreibung %}<div>{{ doc.beschreibung }}</div>{% endif %}
<table class="ph-tabelle"><tr><th>Art</th><th>Raum</th><th>Bezeichnung</th><th>Menge</th><th>Einzel</th><th>Betrag</th></tr>
{% for z in doc.positionen %}<tr><td>{{ {"neu": "Mehrleistung", "entfall": "Entfall", "aenderung": "Änderung"}[z.art] }}</td><td>{{ z.raum or "" }}</td><td>{{ z.bezeichnung }}{% if z.ausfuehrung_text %}<br><span class="ph-klein">{{ z.ausfuehrung_text }}</span>{% endif %}</td><td>{{ z.menge }}</td><td style="text-align:right">{{ ph_betrag(z.einzel_cent) }}</td><td style="text-align:right">{{ ph_betrag(z.betrag_cent) }}</td></tr>{% endfor %}
<tr><td colspan="5" style="text-align:right"><b>Differenz gesamt (brutto)</b></td><td style="text-align:right"><b>{{ ph_betrag(doc.differenz_cent) }}</b></td></tr>
</table>
{% if doc.auswirkung_termin %}<div class="ph-feld"><b>Auswirkung auf Termine</b> {{ doc.auswirkung_termin }}</div>{% endif %}
<p>Mit der Freigabe beauftragt der Kunde die oben genannten Änderungen zu den angegebenen Preisen; alle übrigen Vereinbarungen des Auftrags bleiben unverändert.{% if doc.freigabe_frist %} Bitte geben Sie den Nachtrag bis {{ ph_datum(doc.freigabe_frist) }} frei.{% endif %}</p>
<table style="width:100%;margin-top:12mm"><tr>
<td style="width:50%">{% if doc.unterschrift_kunde %}<img src="{{ doc.unterschrift_kunde }}" style="max-height:22mm"><br>{% endif %}{{ doc.unterschrift_name or "" }}{% if doc.entscheidung_am %}, {{ ph_datum(doc.entscheidung_am) }}{% endif %}{% if doc.entscheidung_quelle == "portal" %} (Freigabe im Kundenportal){% endif %}<br>____________________<br>Kunde</td>
<td style="width:50%">____________________<br>Platzhirsch Home Living</td></tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Auftragsmappe {{ doc.name }}{% endblock %}
{% block kopfrechts %}Auftragsmappe<br>{{ doc.name }}<br>Stand {{ ph_datum(frappe.utils.nowdate()) }}{% endblock %}
{% block inhalt %}
<h1>Auftragsmappe</h1>
<h2>{{ doc.titel }}</h2>
<div class="ph-feld"><b>Kunde</b> {{ doc.kunde_name or "" }}</div>
<div class="ph-feld"><b>Objekt</b> {{ doc.objekt_strasse or "" }} {{ doc.objekt_plz or "" }} {{ doc.objekt_ort or "" }}</div>
<div class="ph-feld"><b>Projektart / Phase</b> {{ _(doc.projektart) }} · {{ _(doc.status) }}</div>
<div class="ph-feld"><b>Team</b> Beratung {{ frappe.db.get_value("User", doc.berater, "full_name") or doc.berater or "–" }} · Planung {{ frappe.db.get_value("User", doc.planer, "full_name") or doc.planer or "–" }} · Montage {{ frappe.db.get_value("User", doc.montageleiter, "full_name") or doc.montageleiter or "–" }}</div>
<div class="ph-feld"><b>Termine</b> Lieferung {{ ph_datum(doc.liefertermin_geplant) or "–" }} · Montage {{ ph_datum(doc.montage_von) or "–" }}–{{ ph_datum(doc.montage_bis) or "–" }} · Übergabe {{ ph_datum(doc.uebergabe_am) or "–" }}</div>
<h2>Positionen je Raum</h2>
<table class="ph-tabelle"><tr><th>Raum</th><th>Pos.</th><th>Bezeichnung</th><th>Lieferant</th><th>Menge</th><th>Lieferstatus</th><th>Liefertermin</th></tr>
{% for z in doc.positionen|sort(attribute="raum") %}<tr><td>{{ z.raum or "" }}</td><td>{{ z.pos_nr or z.idx }}</td><td>{{ z.bezeichnung }}{% if z.ausfuehrung_text %}<br><span class="ph-klein">{{ z.ausfuehrung_text }}</span>{% endif %}</td><td>{{ z.lieferant or z.marke or "" }}</td><td>{{ z.menge_geliefert or 0 }}/{{ z.menge }}</td><td>{{ _(z.lieferstatus or "offen") }}{% if z.nachlieferung_noetig %} · Nachlieferung{% endif %}</td><td>{{ ph_datum(z.liefertermin) or "" }}</td></tr>{% endfor %}
</table>
<p class="ph-klein">Diese Mappe enthält in dieser Reihenfolge: Statusbericht, Aufmaße, Pläne, Nachträge, Montageberichte, Abnahmeprotokolle, Produktpässe – soweit vorhanden. Ohne Preise der Einzelpositionen.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set d = ph_nachkalkulation_daten(doc) %}
{% macro pz(p) %}{{ "–" if p is none else ("%.1f %%" % (p|float)) }}{% endmacro %}
{% block titel %}Nachkalkulation {{ doc.projekt }}{% endblock %}
{% block kopfrechts %}{{ doc.name }}<br>Stichtag {{ ph_datum(doc.stichtag) }}<br>{{ "Abgeschlossen" if doc.status == "Abgeschlossen" else "Entwurf" }}{% endblock %}
{% block css %}
.nk-k{display:flex;gap:3mm;margin:3mm 0 5mm}.nk-k div{flex:1;background:#f3f1ec;border-radius:1mm;padding:2.5mm}.nk-k b{display:block;font-size:12pt;color:#30373e}.nk-k span{font-size:7pt;text-transform:uppercase;letter-spacing:.06em;color:#8a7a66}
table.nk{width:100%;border-collapse:collapse;font-size:8.5pt;margin-bottom:4mm}table.nk th{text-align:left;font-weight:600;border-bottom:.3mm solid #30373e;padding:1.2mm}table.nk td{border-bottom:.1mm solid #ddd;padding:1.2mm;vertical-align:top}table.nk .r{text-align:right;white-space:nowrap}
.a-gruen{color:#15803d}.a-gelb{color:#b45309}.a-rot{color:#b91c1c}.nk-pflicht{color:#b91c1c;font-weight:600}
{% endblock %}
{% block inhalt %}
<h1>{{ doc.titel }}</h1>
<p style="color:#6b7280">{{ _(doc.projektart) if doc.projektart else "" }}{% if doc.berater %} · Berater {{ doc.berater }}{% endif %} · Fertigstellung {{ doc.fertigstellungsgrad }} %{% if doc.ampel %} · Ampel <span class="a-{{ doc.ampel }}">{{ doc.ampel }}</span>{% endif %}</p>
<div class="nk-k">
 <div><span>Erlös netto</span><b>{{ ph_betrag(doc.erloes_cent) }}</b>{{ "gestellt" if doc.erloes_basis == "gestellt" else "Auftragswert" }}</div>
 <div><span>Kosten Ist</span><b>{{ ph_betrag(doc.kosten_ist_cent) }}</b>Budget bei Auftrag {{ ph_betrag(doc.budget_auftrag_cent) }}</div>
 <div><span>DB1</span><b>{{ ph_betrag(doc.db1_cent) }}</b>{{ pz(doc.db1_prozent) }}{% if doc.ziel_db1 %} (Ziel {{ pz(doc.ziel_db1) }}){% endif %}</div>
 <div><span>DB3</span><b>{{ ph_betrag(doc.db3_cent) }}</b>{{ pz(doc.db3_prozent) }}{% if doc.ziel_db3 %} (Ziel {{ pz(doc.ziel_db3) }}){% endif %}</div>
</div>
<h2>Deckungsbeitragsstufen</h2>
<table class="nk">
 <tr><th>Stufe</th><th class="r">Betrag</th><th class="r">% vom Erlös</th><th class="r">Ziel</th></tr>
 <tr><td>Erlös netto</td><td class="r">{{ ph_betrag(doc.erloes_cent) }}</td><td class="r">100,0 %</td><td></td></tr>
 <tr><td>DB1 = Erlös − Wareneinsatz (Ware, Fracht)</td><td class="r">{{ ph_betrag(doc.db1_cent) }}</td><td class="r">{{ pz(doc.db1_prozent) }}</td><td class="r">{{ pz(doc.ziel_db1) if doc.ziel_db1 else "–" }}</td></tr>
 <tr><td>DB2 = DB1 − Montage, Fremdgewerke, Material</td><td class="r">{{ ph_betrag(doc.db2_cent) }}</td><td class="r">{{ pz(doc.db2_prozent) }}</td><td class="r">{{ pz(doc.ziel_db2) if doc.ziel_db2 else "–" }}</td></tr>
 <tr><td>DB3 = DB2 − Planung/Beratung/Projektleitung, Nachlauf</td><td class="r">{{ ph_betrag(doc.db3_cent) }}</td><td class="r">{{ pz(doc.db3_prozent) }}</td><td class="r">{{ pz(doc.ziel_db3) if doc.ziel_db3 else "–" }}</td></tr>
 {% if doc.gemeinkosten_aktiv %}<tr><td>DB4 = DB3 − Gemeinkosten ({{ ph_betrag(doc.gemeinkosten_cent) }})</td><td class="r">{{ ph_betrag(doc.db4_cent) }}</td><td class="r">{{ pz(doc.db4_prozent) }}</td><td></td></tr>{% endif %}
</table>
<h2>Abweichungsanalyse je Kostenart</h2>
<table class="nk">
 <tr><th>Kostenart</th><th>Stufe</th><th class="r">Budget bei Auftrag</th><th class="r">Budget aktuell</th><th class="r">Ist</th><th class="r">Abweichung</th><th class="r">%</th><th>Kommentar</th></tr>
 {% for z in doc.kostenarten %}
 <tr><td>{{ z.kostenart }}</td><td>{{ z.db_stufe or "" }}</td><td class="r">{{ ph_betrag(z.budget_auftrag_cent) }}</td><td class="r">{{ ph_betrag(z.budget_aktuell_cent) }}</td><td class="r">{{ ph_betrag(z.ist_cent) }}</td>
  <td class="r">{{ ph_betrag(z.abweichung_cent) }}</td><td class="r {{ 'nk-pflicht' if z.kommentar_pflicht else '' }}">{{ "%.1f" % z.abweichung_prozent }}</td><td>{{ z.kommentar or ("Kommentar fehlt" if z.kommentar_pflicht else "") }}</td></tr>
 {% endfor %}
 <tr><td><b>Summe</b></td><td></td><td class="r"><b>{{ ph_betrag(doc.budget_auftrag_cent) }}</b></td><td class="r"><b>{{ ph_betrag(doc.budget_aktuell_cent) }}</b></td><td class="r"><b>{{ ph_betrag(doc.kosten_ist_cent) }}</b></td><td class="r"><b>{{ ph_betrag(doc.abweichung_cent) }}</b></td><td></td><td></td></tr>
</table>
<p style="font-size:7.5pt;color:#6b7280">Kommentarpflicht ab Abweichung über {{ doc.schwelle_prozent }} %. Ist = zugeordnete Eingangsrechnungen, Lagerentnahmen zum Einstandswert, Projektzeiten × Kostensatz zum Leistungsdatum, Kassa-Barausgaben, Servicefälle nach Übergabe abzüglich Regress.</p>
{% if doc.lernwerte %}
<h2>Lernwerte Montagezeit</h2>
<table class="nk">
 <tr><th>Kategorie</th><th class="r">Stück</th><th class="r">Plan (min)</th><th class="r">Ist anteilig (min)</th><th class="r">Ist je Stück</th><th class="r">Richtwert bisher</th></tr>
 {% for z in doc.lernwerte %}<tr><td>{{ z.kategorie }}</td><td class="r">{{ z.menge }}</td><td class="r">{{ z.plan_min }}</td><td class="r">{{ z.ist_min }}</td><td class="r">{{ z.min_je_stueck }}</td><td class="r">{{ z.richtwert_min or "–" }}</td></tr>{% endfor %}
</table>
{% endif %}
{% set quellen = (d.get("quellen") or [])|sort(attribute="betrag_cent", reverse=True) %}
{% if quellen %}
<h2>Größte Kostenbelege</h2>
<table class="nk">
 <tr><th>Datum</th><th>Beleg</th><th>Kostenart</th><th>Text</th><th class="r">Betrag</th><th>Art</th></tr>
 {% for q in quellen[:25] %}<tr><td>{{ ph_datum(q.datum) if q.datum else "" }}</td><td>{{ q.quelle_name or "" }}</td><td>{{ q.kostenart or "" }}</td><td>{{ (q.text or "")[:60] }}</td><td class="r">{{ ph_betrag(q.betrag_cent) }}</td><td>{{ "Obligo" if q.typ == "obligo" else "Ist" }}</td></tr>{% endfor %}
</table>
{% endif %}
{% if doc.fazit %}<h2>Fazit</h2><div>{{ doc.fazit }}</div>{% endif %}
{% if doc.abgeschlossen_von %}<p style="font-size:8pt;color:#6b7280;margin-top:6mm">Abgeschlossen von {{ doc.abgeschlossen_von }} am {{ ph_datum(doc.abgeschlossen_am) }}</p>{% endif %}
{% endblock %}
